import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.MapInfoRequest{MapID: -5, ClientPixels: []protocol.PixelRequest{
# {Colour: color.RGBA{R: 0x04, G: 0x03, B: 0x02, A: 0x01}, Index: 0x0102},
# {Colour: color.RGBA{R: 0xff, G: 0xff, B: 0xff, A: 0xff}, Index: 7}}}
PIXELS = bytes.fromhex("0902000000040302010201ffffffff0700")

# generated by gophertunnel b8bd735:
# &packet.MapInfoRequest{}
EMPTY = bytes.fromhex("0000000000")

GOLDENS = [
    pytest.param(
        v2225.MapInfoRequestPacket(
            map_id=-5,
            client_pixels=[
                v2225.MapInfoRequestPacket.ClientPixelsProxy(pixel=0x01020304, index=0x0102),
                v2225.MapInfoRequestPacket.ClientPixelsProxy(pixel=0xFFFFFFFF, index=7),
            ],
        ),
        PIXELS,
        id="pixels",
    ),
    pytest.param(v2225.MapInfoRequestPacket(map_id=0), EMPTY, id="no-pixels"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_map_info_request_is_packet_68(version):
    assert version.PACKETS[68] is version.MapInfoRequestPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_map_info_request_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_map_info_request_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
